-- Начальные данные каталога. Сгенерировано scripts/generate-seed.ts —
-- править этот файл руками бессмысленно, он перезаписывается.

begin;

-- ── посты ──
insert into public.posts (slug, title, subtitle, category_id, cover, blocks, read_min, published, sort_order) values (
  'remotion-video-kodom', 'Видео через Claude Code', 'Remotion Skills: вы описываете ролик словами, на выходе — готовый MP4', 'ai',
  '{"from":"#F04A1E","to":"#2A0E0A","pattern":"grid","imageUrl":"https://kyutpzudsiifhdxysyff.supabase.co/storage/v1/object/public/covers/remotion-video-kodom.jpg"}'::jsonb, '[{"type":"text","text":"Remotion Skills — это инструкции, по которым Claude Code создаёт видео. Вы описываете результат, Claude пишет код, а Remotion превращает его в MP4. Ни таймлайна, ни ползунков, ни ручных ключевых точек."},{"type":"text","text":"Дальше — весь путь по шагам: от пустой папки до файла, который можно выложить. Команды выполняются в терминале, промты вставляются в Claude Code."},{"type":"callout","tone":"info","text":"Из подготовки нужен только установленный Node.js. Всё остальное поставится по ходу дела."},{"type":"heading","text":"1. Создайте проект"},{"type":"text","text":"Четыре команды в терминале, по очереди."},{"type":"command","command":"npx create-video@latest my-video","note":"Задаст пару вопросов и соберёт заготовку проекта."},{"type":"command","command":"cd my-video"},{"type":"command","command":"npx skills add remotion-dev/skills","note":"Те самые инструкции: создание, студия, субтитры, рендер."},{"type":"command","command":"claude","note":"Если появится выбор агента — выберите Claude Code."},{"type":"heading","text":"2. Опишите видео"},{"type":"text","text":"Первое сообщение задаёт рамку: формат, длину, тему и стиль. В квадратных скобках подставьте своё."},{"type":"prompt","title":"Задание на ролик","text":"/remotion-create\n\nСоздай вертикальное видео:\n\n- размер: 1080×1920;\n- 30 FPS;\n- длительность: до 30 секунд;\n- тема: [ОПИШИТЕ ТЕМУ];\n- стиль: [ЦВЕТА И АТМОСФЕРА];\n- без людей и готовых видео;\n- вся графика — React, SVG и Remotion;\n- текст и элементы появляются с анимацией;\n- композиция меняется каждые 2–3 секунды;\n- нижние 15% оставь для субтитров.\n\nСначала покажи короткий план сцен.\nПока не пиши код."},{"type":"callout","tone":"warning","text":"Две последние строки важнее, чем кажется. План из пяти строк правится словами за минуту, готовые сцены — переписываются заново."},{"type":"text","text":"Claude покажет план сцен. Если всё подходит — отвечаете:"},{"type":"prompt","title":"Согласование плана","text":"План подходит. Реализуй всё видео.\nРаздели сцены на компоненты и после проверки запусти Remotion Studio."},{"type":"heading","text":"3. Посмотрите результат"},{"type":"prompt","text":"/remotion-studio"},{"type":"text","text":"Claude запустит редактор и даст ссылку. Откройте её в браузере: там таймлайн, перемотка и мгновенное обновление после каждой правки кода."},{"type":"heading","text":"4. Попросите исправления"},{"type":"text","text":"Правка срабатывает, когда в ней есть время, проблема и рамка — что именно не трогать."},{"type":"prompt","title":"Скорость анимации","text":"На 5-й секунде заголовок появляется слишком медленно.\nУскорь только эту анимацию."},{"type":"prompt","title":"Обрезанный текст","text":"На 12-й секунде текст обрезается справа.\nИсправь отступы, остальные сцены не меняй."},{"type":"prompt","title":"Порядок появления","text":"Карточки появляются одновременно.\nПокажи их по очереди с небольшой задержкой."},{"type":"callout","tone":"info","text":"После каждой правки возвращайтесь в Studio и пересматривайте сцену. Накопить десять исправлений и проверить всё разом — верный способ не понять, какое из них сломало соседнюю сцену."},{"type":"heading","text":"5. Добавьте озвучку"},{"type":"text","text":"Если запись уже есть, положите файл в проект по пути public/voiceover.mp3 и напишите:"},{"type":"prompt","title":"Подключить свою запись","text":"Подключи public/voiceover.mp3 к видео.\nОпредели реальную длительность аудио и синхронизируй с ним все сцены.\nНе обрезай начало и конец записи."},{"type":"text","text":"Если озвучки нет — её сделает бесплатный Edge TTS. Голос стоит выбрать самому: просите варианты до того, как появится финальный файл."},{"type":"prompt","title":"Озвучка через Edge TTS","text":"Создай русскую озвучку через бесплатный Edge TTS.\n\nСначала подготовь три коротких варианта голоса:\nA — энергичный мужской;\nB — спокойный мужской;\nC — уверенный женский.\n\nДай мне прослушать варианты и дождись моего выбора.\nПосле выбора сохрани финальный файл как public/voiceover.mp3."},{"type":"callout","tone":"warning","text":"Длину ролика задаёт аудио, а не вы. Вбитая руками длительность — причина половины проблем в готовых видео: голос обрывается на полуслове или в конце висит секунда тишины."},{"type":"heading","text":"6. Добавьте субтитры"},{"type":"text","text":"Субтитры строятся по реальным таймкодам озвучки. Место под них вы уже оставили в первом задании — нижние 15% кадра."},{"type":"prompt","title":"Субтитры по таймкодам","text":"/remotion-captions\n\nСоздай субтитры по реальным таймкодам озвучки:\n\n- максимум две строки;\n- крупный белый текст;\n- ключевые слова выделяй цветом;\n- показывай целыми фразами;\n- размести выше нижнего края;\n- точно синхронизируй с голосом."},{"type":"heading","text":"7. Получите MP4"},{"type":"text","text":"Перед рендером имеет смысл прогнать проверку: поймать ошибку в коде дешевле, чем обнаружить её в готовом файле."},{"type":"prompt","title":"Проверка и рендер","text":"/remotion-render\n\nПеред рендером проверь:\n\n- ошибки TypeScript;\n- синхронизацию озвучки;\n- субтитры;\n- обрезанный текст;\n- безопасные зоны Instagram;\n- продолжительность видео.\n\nИсправь найденные проблемы и сохрани готовое видео как out/video.mp4."},{"type":"text","text":"Готовый файл появится в проекте: my-video/out/video.mp4. Его можно выкладывать в Reels, Shorts или Telegram."},{"type":"heading","text":"Весь процесс"},{"type":"list","ordered":true,"items":["Создать проект.","Установить Remotion Skills.","Запустить Claude Code.","Описать видео и согласовать план сцен.","Проверить результат в Studio и попросить правки.","Добавить озвучку и субтитры.","Отрендерить MP4."]},{"type":"callout","tone":"success","text":"Ни монтажной программы, ни таймлайна: описание словами, код и рендер. Первый ролик проходит весь путь за вечер."}]'::jsonb, 5, true, 2
) on conflict (slug) do update set
  title = excluded.title, subtitle = excluded.subtitle, category_id = excluded.category_id,
  cover = excluded.cover, blocks = excluded.blocks,
  read_min = excluded.read_min, sort_order = excluded.sort_order;

commit;
